  app.post('/api/v1/admin/bookings/:id/claim', requirePermission(store, 'bookings:manage'), async (req, res) => { const existing = await store.findBooking(String(req.params.id)); assert(existing, 404, 'BOOKING_NOT_FOUND', 'Booking not found'); if (existing.ownerId && existing.ownerId !== req.user!.id) throw new AppError(409, 'BOOKING_ALREADY_CLAIMED', 'This booking is already assigned to another operator'); const booking = await store.claimBooking(existing.id, req.user!.id); assert(booking, 409, 'BOOKING_ALREADY_CLAIMED', 'This booking is already assigned to another operator'); await store.audit('admin.booking_claimed', { ...clientMeta(req), userId: req.user!.id, metadata: { bookingId: existing.id } }); res.json({ booking }); });
  app.post('/api/v1/admin/bookings/:id/release', requirePermission(store, 'bookings:manage'), async (req, res) => { const existing = await store.findBooking(String(req.params.id)); assert(existing, 404, 'BOOKING_NOT_FOUND', 'Booking not found'); const booking = await store.releaseBooking(existing.id, req.user!.id, isPrivileged(req)); assert(booking, 403, 'BOOKING_OWNER_REQUIRED', 'Only the assigned operator can release this booking'); await store.audit('admin.booking_released', { ...clientMeta(req), userId: req.user!.id, metadata: { bookingId: existing.id } }); res.json({ booking }); });
  app.patch('/api/v1/admin/bookings/:id', requirePermission(store, 'bookings:manage'), async (req, res) => { const input = toInput(adminBookingPatchRequest, req.body); const existing = await store.findBooking(String(req.params.id)); assert(existing, 404, 'BOOKING_NOT_FOUND', 'Booking not found'); assert(isPrivileged(req) || existing.ownerId === req.user!.id, 403, 'BOOKING_OWNER_REQUIRED', 'Claim this booking before changing it'); if (input.ownerId !== undefined) { assertPrivileged(req); if (input.ownerId) { const assignee = await store.findUserById(input.ownerId); assert(assignee && ['manager', 'admin', 'super_admin', 'support', 'content_manager', 'finance'].includes(assignee.role) && assignee.status === 'active', 400, 'INVALID_ASSIGNEE', 'Choose an active admin or operator'); } } if (input.status && input.status !== existing.status) { assert(bookingTransitions[existing.status].includes(input.status), 409, 'INVALID_BOOKING_TRANSITION', `A ${existing.status} booking cannot move directly to ${input.status}`); } const action = input.ownerId !== undefined ? 'assignee_changed' : input.request !== undefined ? 'request_updated' : input.status ? 'status_changed' : 'note_added'; const booking = await store.updateAdminBooking(existing.id, { status: input.status, internalNote: input.internalNote, ownerId: input.ownerId, request: input.request }, req.user!.id, action); assert(booking, 404, 'BOOKING_NOT_FOUND', 'Booking not found'); await store.audit('admin.booking_updated', { ...clientMeta(req), userId: req.user!.id, metadata: { bookingId: existing.id, previousStatus: existing.status, status: input.status, previousOwnerId: existing.ownerId, ownerId: input.ownerId } }); res.json({ booking, history: await store.listBookingEvents(existing.id) }); });

